// Prepare generation context and split into tasks (one per content piece)
const body = $('Webhook').item.json.body || $('Webhook').item.json;

const {
  generation_run_id,
  personality_dna_id,
  audience_dna_id,
  product_dna_id,
  count,
  script_format,
  target_platform,
  personality_dna,
  audience_dna,
  product_dna,
  rules,
  content,
  supabase_url,
  supabase_service_key
} = body;

console.log(`Generation run ${generation_run_id}: ${content?.length || 0} content pieces, ${rules?.length || 0} rules`);

if (!content || content.length === 0) {
  console.log('No content available to model. Checking for rules...');
  // Return a single task to handle the no-content case
  return [{
    json: {
      _no_content: true,
      _run_id: generation_run_id,
      _supabase_url: supabase_url,
      _supabase_key: supabase_service_key
    }
  }];
}

// Build one task per content piece, matched to its referente rule
const tasks = [];
const maxTasks = Math.min(content.length, count || 10);

for (let i = 0; i < maxTasks; i++) {
  const piece = content[i];
  const rule = rules?.find(r => r.referente_id === piece.referente_id) || rules?.[0] || null;

  tasks.push({
    json: {
      _run_id: generation_run_id,
      _supabase_url: supabase_url,
      _supabase_key: supabase_service_key,
      _personality_dna: personality_dna,
      _audience_dna: audience_dna,
      _product_dna: product_dna,
      _rule: rule,
      _content: piece,
      _script_format: script_format || 'video_script',
      _target_platform: target_platform || 'multi',
      _personality_dna_id: personality_dna_id,
      _audience_dna_id: audience_dna_id,
      _product_dna_id: product_dna_id
    }
  });
}

console.log(`Created ${tasks.length} generation tasks`);
return tasks;

// Update generation_run as failed (no content)
const task = $input.first().json;
try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${task._supabase_url}/rest/v1/generation_runs?id=eq.${task._run_id}`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: {
      status: 'failed',
      completed_at: new Date().toISOString(),
      error_message: 'No hay contenido disponible. Agrega referentes con reglas de modelado y espera a que el banco de contenido se llene.'
    },
    json: true
  });
} catch(e) {
  console.log('Failed to update run:', e.message);
}
return [{ json: { done: true, error: 'no_content' } }];

// Build Claude Opus prompt from DNA + content + rule
const task = $input.first().json;
const pd = task._personality_dna?.data || {};
const ad = task._audience_dna?.data || {};
const prod = task._product_dna?.data || {};
const content = task._content || {};
const rule = task._rule || {};
const fmt = task._script_format || 'video_script';
const platform = task._target_platform || 'multi';

// Format DNA data as readable text
const personalityText = [
  pd.about ? `Quién soy: ${pd.about}` : '',
  pd.voice ? `Mi voz y estilo: ${pd.voice}` : '',
  pd.credentials ? `Credenciales: ${pd.credentials}` : '',
  pd.forbidden_words ? `Palabras PROHIBIDAS: ${pd.forbidden_words}` : ''
].filter(Boolean).join('\n');

const audienceText = [
  ad.ideal_client ? `Cliente ideal: ${ad.ideal_client}` : '',
  ad.core_belief ? `Creencia central: ${ad.core_belief}` : '',
  ad.testimonials ? `Prueba social: ${ad.testimonials}` : '',
  ad.keywords ? `Palabras que usan: ${ad.keywords}` : ''
].filter(Boolean).join('\n');

const productText = [
  prod.main_problem ? `Problema que resuelvo: ${prod.main_problem}` : '',
  prod.solution_promise ? `Promesa de solución: ${prod.solution_promise}` : '',
  prod.irresistible_offer ? `Oferta: ${prod.irresistible_offer}` : '',
  prod.keywords ? `Keywords: ${prod.keywords}` : ''
].filter(Boolean).join('\n');

const contentText = [
  content.original_caption ? `Caption/Texto original:\n${content.original_caption.substring(0, 3000)}` : '',
  content.transcript ? `Transcripción:\n${content.transcript.substring(0, 2000)}` : '',
  content.media_analysis ? `Análisis visual: ${content.media_analysis.substring(0, 500)}` : '',
  content.strategic_analysis ? `Análisis estratégico: ${content.strategic_analysis.substring(0, 500)}` : '',
  content.content_structure ? `Estructura detectada: ${content.content_structure.substring(0, 300)}` : '',
  content.views ? `Vistas: ${content.views.toLocaleString()}` : '',
  content.likes ? `Likes: ${content.likes.toLocaleString()}` : '',
  content.days_active ? `Días activo: ${content.days_active}` : ''
].filter(Boolean).join('\n');

const userPrompt = `=== DNA DEL CLIENTE ===
Personalidad/Voz:
${personalityText || 'Sin datos'}

Audiencia/Avatar:
${audienceText || 'Sin datos'}

Producto/Oferta:
${productText || 'Sin datos'}

=== REFERENTE ===
Nombre: ${rule.referentes?.name || content.referente_id || 'Referente'}
Qué MODELAR de este referente: ${rule.what_to_model || 'Estructura y framework de persuasión'}
Qué FILTRAR de este referente: ${rule.what_to_filter || 'Elementos no aplicables al DNA'}

=== CONTENIDO ORIGINAL A MODELAR ===
Plataforma: ${content.platform}
Tipo: ${content.content_type}
${contentText}

=== FORMATO DE ENTREGA ===
Formato: ${fmt}
Plataforma destino: ${platform}

Responde ÚNICAMENTE con este JSON válido (sin texto adicional, sin backticks):
{
  "hook_1": "El hook principal. Para video_script: incluir [NOTAS DE PRODUCCIÓN] entre corchetes.",
  "hook_2": "Un segundo hook con un ángulo DIFERENTE al hook 1.",
  "body": "El cuerpo. Para video_script: incluir [NOTAS DE PRODUCCIÓN] entre corchetes.",
  "cta": "Call to action con urgencia y acción clara.",
  "production_notes": "Notas generales de producción. null si es written_ad.",
  "what_was_modeled": "Qué se tomó del referente.",
  "why_it_works": "Por qué el original funciona (1-2 oraciones).",
  "how_adapted": "Cómo se adaptó al DNA."
}`;

return [{ json: { ...task, _user_prompt: userPrompt } }];

// Parse Claude response and save to Supabase
const task = $('Build Prompt').item.json;
let parsed = null;

try {
  const res = $input.first().json;
  const text = res.content?.[0]?.text || '';
  // Find JSON in the response
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  }
} catch(e) {
  console.log('Parse error:', e.message);
}

if (!parsed || !parsed.hook_1 || !parsed.body || !parsed.cta) {
  console.log('Invalid or empty response from Claude, skipping save');
  return [{ json: { ...task, _saved: false, _error: 'invalid_response' } }];
}

// Save script to Supabase
const script = {
  personality_dna_id: task._personality_dna_id,
  audience_dna_id: task._audience_dna_id,
  product_dna_id: task._product_dna_id,
  source_content_id: task._content?.id || null,
  referente_id: task._content?.referente_id || null,
  referente_name: task._rule?.referentes?.name || null,
  hook_1: parsed.hook_1,
  hook_2: parsed.hook_2 || null,
  body: parsed.body,
  cta: parsed.cta,
  production_notes: parsed.production_notes || null,
  script_format: task._script_format,
  target_platform: task._target_platform,
  what_was_modeled: parsed.what_was_modeled || null,
  why_it_works: parsed.why_it_works || null,
  how_adapted: parsed.how_adapted || null,
  status: 'draft',
  model_used: 'claude-opus-4-6'
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${task._supabase_url}/rest/v1/modeled_scripts`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: script,
    json: true
  });
  console.log(`Saved script for referente: ${script.referente_name}`);
} catch(e) {
  console.log('Save script error:', e.message);
  return [{ json: { ...task, _saved: false, _error: e.message } }];
}

// Mark content as used
if (task._content?.id) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${task._supabase_url}/rest/v1/referente_content?id=eq.${task._content.id}`,
      headers: {
        'Authorization': `Bearer ${task._supabase_key}`,
        'apikey': task._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: { is_used: true },
      json: true
    });
  } catch(e) {
    console.log('Mark used error:', e.message);
  }
}

return [{ json: { ...task, _saved: true } }];

// After loop: update generation_run to completed
const allItems = $('Parse & Save').all();
const first = allItems[0]?.json || {};
const savedCount = allItems.filter(i => i.json._saved).length;

console.log(`Loop complete. Saved ${savedCount} of ${allItems.length} scripts.`);

if (first._run_id) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${first._supabase_url}/rest/v1/generation_runs?id=eq.${first._run_id}`,
      headers: {
        'Authorization': `Bearer ${first._supabase_key}`,
        'apikey': first._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        status: savedCount > 0 ? 'completed' : 'failed',
        completed_at: new Date().toISOString(),
        generated_count: savedCount,
        error_message: savedCount === 0 ? 'No scripts were saved' : null
      },
      json: true
    });
    console.log(`Generation run ${first._run_id} marked as ${savedCount > 0 ? 'completed' : 'failed'}`);
  } catch(e) {
    console.log('Update run error:', e.message);
  }
}

return [{ json: { done: true, saved: savedCount, total: allItems.length } }];
